import React, { useState } from 'react';
import { Navigation, AlertCircle, Database, CheckCircle } from 'lucide-react';

const ScheduleTab = ({ onNavigateToReports }) => {
  const [verifyingId, setVerifyingId] = useState(null);
  const [isVerified, setIsVerified] = useState(false);

  const schedule = [
    { id: 'LOC_04', time: '08:00', area: 'Sector 4', hasReport: true, binLevel: 88 },
    { id: 'LOC_09', time: '10:30', area: 'Zone B', hasReport: false, binLevel: 92 },
  ];

  const handleJobDone = (id) => {
    setVerifyingId(id);
    setIsVerified(false);
    // Simulate admin/sensor verification
    setTimeout(() => setIsVerified(true), 2000);
  };

  return (
    <div className="w-full max-w-lg animate-slide-up space-y-6">
      <h3 className="text-4xl font-black italic text-[#47510B] uppercase tracking-tighter px-4">Assignments.</h3>

      {schedule.map((item) => (
        <div key={item.id} className="bg-white p-6 rounded-[45px] border-4 border-[#47510B] shadow-[8px_8px_0_0_#47510B] relative">
          <div className="flex justify-between items-start">
            <div>
              <span className="text-[10px] font-black opacity-30 uppercase tracking-widest">{item.time} // {item.id}</span>
              <h4 className="text-3xl font-black text-[#47510B] uppercase italic">{item.area}</h4>

              {item.hasReport && (
                <button 
                  onClick={onNavigateToReports}
                  className="mt-3 flex items-center gap-2 bg-[#AB1717] text-white px-3 py-1 rounded-full text-[10px] font-black uppercase animate-pulse"
                >
                  <AlertCircle size={12} /> View Report
                </button>
              )}
            </div>
            <button onClick={() => alert("GPS Route Opening...")} className="bg-[#47510B] text-[#CAD23C] p-4 rounded-2xl active:scale-90 transition-all">
              <Navigation size={24} />
            </button>
          </div>

          <button 
            onClick={() => handleJobDone(item.id)}
            className="mt-6 w-full py-4 bg-[#CAD23C] border-2 border-[#47510B] rounded-2xl font-black uppercase text-[#47510B] hover:bg-[#47510B] hover:text-[#CAD23C] transition-all"
          >
            Mark as Done
          </button>
        </div>
      ))}

      {/* --- ADMIN VERIFICATION MODAL --- */}
      {verifyingId && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-[#47510B]/90 backdrop-blur-md">
          <div className="bg-[#FDFAD8] p-8 rounded-[50px] border-[10px] border-white w-full max-w-sm text-center">
            <Database size={50} className={`mx-auto mb-4 ${!isVerified ? 'animate-bounce text-[#47510B]' : 'text-[#CAD23C]'}`} />
            <h3 className="text-2xl font-black uppercase italic text-[#47510B]">
              {isVerified ? "Verified" : "Admin_Sync"}
            </h3>

            <div className="p-6 bg-white rounded-3xl border-2 border-[#47510B] my-6">
              <p className="text-[10px] font-black opacity-30 uppercase">Sensor Data: Bin Fill Level</p>
              <p className={`text-5xl font-black ${isVerified ? 'text-[#CAD23C]' : 'text-[#AB1717]'}`}>
                {isVerified ? "08%" : "88%"}
              </p>
            </div>

            <button 
              disabled={!isVerified}
              onClick={() => setVerifyingId(null)}
              className={`w-full py-5 rounded-[25px] font-black uppercase text-xl transition-all ${isVerified ? 'bg-[#47510B] text-[#CAD23C]' : 'bg-gray-300 text-gray-500'}`}
            >
              {isVerified ? "Confirm Mission" : "Verifying..."}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ScheduleTab;
